class C {
    public required string Name;
    public C Self { get { Print("unexpected getter"); Print(Name); return this; } }
}
void Main() {
    var first = new C { Self = {}, Name = "first" };
    var second = new C { Self = { Self = { Self = {} } }, Name = "second" };
    Print(first.Name); Print(second.Name);
}
